CREATE TABLE users (id text PRIMARY KEY NOT NULL, role text NOT NULL, name text NOT NULL, college text, password_hash text NOT NULL, password_salt text NOT NULL, locked integer DEFAULT false NOT NULL, disqualified integer DEFAULT false NOT NULL, created_at integer NOT NULL);
CREATE INDEX idx_users_role ON users (role);
CREATE TABLE rounds (id text PRIMARY KEY NOT NULL, status text DEFAULT 'waiting' NOT NULL, duration_seconds integer NOT NULL, started_at integer, paused_at integer, accumulated_pause_seconds integer DEFAULT 0 NOT NULL, results_published integer DEFAULT false NOT NULL, updated_at integer NOT NULL);
CREATE TABLE participants (user_id text PRIMARY KEY NOT NULL, quiz_submitted_at integer, quiz_correct integer DEFAULT 0 NOT NULL, coins integer DEFAULT 0 NOT NULL, coding_score integer DEFAULT 0 NOT NULL, language text, current_question integer DEFAULT 1 NOT NULL, solved integer DEFAULT 0 NOT NULL, helps_used integer DEFAULT 0 NOT NULL, completion_time integer, status text DEFAULT 'waiting' NOT NULL, last_seen integer NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE cascade);
CREATE TABLE quiz_questions (id integer PRIMARY KEY AUTOINCREMENT NOT NULL, category text NOT NULL, difficulty text NOT NULL, prompt text NOT NULL, options_json text NOT NULL, correct_index integer NOT NULL, coin_value integer NOT NULL);
CREATE TABLE quiz_answers (participant_id text NOT NULL, question_id integer NOT NULL, answer_index integer NOT NULL, answered_at integer NOT NULL, PRIMARY KEY(participant_id, question_id), FOREIGN KEY (participant_id) REFERENCES users(id) ON DELETE cascade, FOREIGN KEY (question_id) REFERENCES quiz_questions(id) ON DELETE cascade);
CREATE INDEX idx_quiz_answers_participant ON quiz_answers (participant_id);
CREATE TABLE coding_questions (id integer PRIMARY KEY NOT NULL, title text NOT NULL, difficulty text NOT NULL, points integer NOT NULL, statement text NOT NULL, input_format text NOT NULL, output_format text NOT NULL, sample_input text NOT NULL, sample_output text NOT NULL, hints_json text NOT NULL);
CREATE TABLE test_cases (id integer PRIMARY KEY AUTOINCREMENT NOT NULL, question_id integer NOT NULL, input text NOT NULL, expected_output text NOT NULL, position integer NOT NULL, FOREIGN KEY (question_id) REFERENCES coding_questions(id) ON DELETE cascade);
CREATE UNIQUE INDEX idx_test_cases_question_position ON test_cases (question_id, position);
CREATE TABLE submissions (id integer PRIMARY KEY AUTOINCREMENT NOT NULL, participant_id text NOT NULL, question_id integer NOT NULL, language text NOT NULL, source text NOT NULL, passed_count integer DEFAULT 0 NOT NULL, verdict text NOT NULL, judge_reference text, created_at integer NOT NULL, FOREIGN KEY (participant_id) REFERENCES users(id) ON DELETE cascade, FOREIGN KEY (question_id) REFERENCES coding_questions(id));
CREATE INDEX idx_submissions_participant_created ON submissions (participant_id, created_at);
CREATE TABLE solved_problems (participant_id text NOT NULL, question_id integer NOT NULL, solved_at integer NOT NULL, points_awarded integer NOT NULL, PRIMARY KEY(participant_id, question_id), FOREIGN KEY (participant_id) REFERENCES users(id) ON DELETE cascade, FOREIGN KEY (question_id) REFERENCES coding_questions(id));
CREATE TABLE help_purchases (id integer PRIMARY KEY AUTOINCREMENT NOT NULL, participant_id text NOT NULL, question_id integer NOT NULL, kind text NOT NULL, cost integer NOT NULL, language text NOT NULL, content text NOT NULL, created_at integer NOT NULL, FOREIGN KEY (participant_id) REFERENCES users(id) ON DELETE cascade, FOREIGN KEY (question_id) REFERENCES coding_questions(id));
CREATE INDEX idx_help_participant ON help_purchases (participant_id);
CREATE TABLE coin_transactions (id integer PRIMARY KEY AUTOINCREMENT NOT NULL, participant_id text NOT NULL, type text NOT NULL, description text NOT NULL, balance_before integer NOT NULL, amount integer NOT NULL, balance_after integer NOT NULL, created_at integer NOT NULL, FOREIGN KEY (participant_id) REFERENCES users(id) ON DELETE cascade);
CREATE INDEX idx_coin_transactions_participant_created ON coin_transactions (participant_id, created_at);
